// Potenciômetro controla o brilho do LED (PWM no pino 9)
const int pot = A0;
const int led = 9;

void setup() {
  pinMode(led, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int leitura = analogRead(pot);               // 0 a 1023
  int brilho = map(leitura, 0, 1023, 0, 255);  // 0 a 255
  analogWrite(led, brilho);
  Serial.print("leitura: ");
  Serial.print(leitura);
  Serial.print("  brilho: ");
  Serial.println(brilho);
  delay(100);
}

