// Mostra também a tensão em volts no potenciômetro
const int pot = A0;
const int led = 9;

void setup() {
  pinMode(led, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int leitura = analogRead(pot);
  float volts = leitura * 5.0 / 1023.0;
  analogWrite(led, map(leitura, 0, 1023, 0, 255));
  Serial.print(volts);
  Serial.println(" V");
  delay(200);
}
